import{_ as i,o as n,c as a,aj as e}from"./chunks/framework.BdtAaXf2.js";const t="/assets/arch-deveco-code.qLdjnkwx.png",l="/assets/image-20260709123302879.DfpuRWNy.png",p="/assets/image-20260709112350165.Cguw1jHk.png",h="/assets/image-20260709112622225.D9lbKrw3.png",o="/assets/image-20260709113513130.DaAL7XTU.png",r="/assets/image-20260709114201159.CBp0mSSp.png",d="/assets/image-20260709114810159.DeF3KSBJ.png",k="/assets/image-20260709130954284.B6V-GHbT.png",c="/assets/image-20260709115138993.CSeX9BXO.png",E="/assets/image-20260709115508859.DVrQw_wn.png",u="/assets/image-20260709115450561.BTJA4a5B.png",g="/assets/image-20260709115625515.BkoYnY95.png",m="/assets/image-20260709115804390.Bsp7K-iE.png",y="/assets/dev-workflow.ynF-Afnk.png",C="/assets/image-20260709123537975.CYsBpjN5.png",F="/assets/image-20260709123823615.CU1z4mIW.png",b="/assets/image-20260709124042817.bzPflZUS.png",q="/assets/image-20260709124451750.CzNghByd.png",v="/assets/image-20260709125229725.DcUw9Y49.png",D="/assets/image-20260709125454619.CShpCj_U.png",B="/assets/image-20260709125700685.BfDyEaMU.png",A="/assets/image-20260709130341246.BNf8-z4y.png",_="/assets/PixPin_2026-07-09_13-10-32.BFQ_GNH6.gif",f="/assets/dev-modes.BpJm9G1Y.png",M=JSON.parse('{"title":"手把手带你上手鸿蒙应用开发利器 DevEcoCode","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/手把手带你上手鸿蒙应用开发利器 DevEcoCli和DevEcoCode/02-手把手带你上手鸿蒙应用开发利器 DevEcoCode/手把手带你上手鸿蒙应用开发利器 DevEcoCode.md","filePath":"鸿蒙开发技巧/手把手带你上手鸿蒙应用开发利器 DevEcoCli和DevEcoCode/02-手把手带你上手鸿蒙应用开发利器 DevEcoCode/手把手带你上手鸿蒙应用开发利器 DevEcoCode.md","lastUpdated":1784253000000,"__rawMarkdown":"# 手把手带你上手鸿蒙应用开发利器 DevEcoCode\\n\\n## 前言\\n\\n接上篇 **《手把手带你上手鸿蒙应用开发利器 DevEcoCli》**\\n\\n> DevEcoCli 是一个面向 HarmonyOS 应用开发的统一命令行入口。\\n>\\n> `DevEcoCli` 将 `DevEco Studio` 工具链统一封装为一个 `CLI`，内置 `ohpm`、`hvigor`、`hdc`、`emulator`、`hilog`，同时集成 HarmonyOS 技能安装、项目脚手架、本地 HarmonyOS 文档检索和 `MCP` 服务。\\n\\n---\\n\\n虽然DevEcoCli提供了众多对标**DevEco Studio**工具的能力，但是如果直接使用**DevEcoCli**对于开发者来说，还是需要记忆不少相关命令，还是会出现记错、记漏以及太依赖开发者的主动性，不能完全发挥DevEcoCli的能力。\\n\\n因此在目前流行的开发流程中，DevEcoCli一定是结合相关的AI工具（agent）来使用的。开发者可以选择自己习惯的AI工具，如Cursor、Trae、Codex等配合DevEcoCli来使用。\\n\\n## DevEcoCode 介绍\\n\\n但是！但是！但是！万少这里是强烈推荐使用鸿蒙官方推出的DevEcoCode。\\n\\nDevEcoCode 是一款面向 HarmonyOS 开发场景的 AI Agent 工具，支持代码编写、编译构建、设备运行、文档查阅、运行时调试及 ArkTS 问题修复等能力。\\n\\nDevEcoCode 基于开源项目 OpenCode 扩展开发，保留了 OpenCode 的终端交互、配置体系、Provider / MCP / Skill / Plugin 等能力，并针对 HarmonyOS 工程增加了 DevEco Studio、Hvigor、HDC、Skill、HarmonyOS 知识库、ArkTS 检查和设备调试相关集成。\\n\\n大白话总结就是——专门为 HarmonyOS 开发而生。\\n\\n可以用下面这张图来理解 DevEcoCode 的整体能力架构，以及它与 DevEcoCli、DevEco Studio 工具链之间的调用关系：\\n\\n![DevEcoCode 能力架构](assets/arch-deveco-code.png)\\n\\n另外需要注意的是，使用DevEcoCode之前，需要先安装好DevEcoCli，因为上面提到的大部分能力都是在底层通过mcp tool的方式调用了DevEcoCli的能力。\\n\\n![](assets/image-20260709123302879.png)\\n\\n## DevEcoCode 前置环境\\n\\n- 目前提供 Windows 与 macOS 版本，暂不支持鸿蒙 PC（小道消息：Q4 可能会支持）\\n\\n  - [Node.js](https://link.atomgit.com/?target=https%3A%2F%2Fnodejs.org&from=https%3A%2F%2Fatomgit.com%2Fopenharmony-sig%2Fdeveco-code&lang=zh&theme=white) **22 及以上**\\n\\n  - [DevEco Studio](https://link.atomgit.com/?target=https%3A%2F%2Fdeveloper.huawei.com%2Fconsumer%2Fcn%2Fdeveco-studio%2F&from=https%3A%2F%2Fatomgit.com%2Fopenharmony-sig%2Fdeveco-code&lang=zh&theme=white) **6.1 及以上**（编译构建、Hvigor、HDC、模拟器/真机运行）\\n\\n  - 已配置 `DEVECO_HOME` 环境变量，指向 DevEco Studio 安装目录\\n\\n    ![](assets/image-20260709112350165.png)\\n\\n## DevEcoCode 安装\\n\\n打开终端，输入命令进行安装。\\n\\n```\\nnpm install -g @deveco/deveco-code\\n```\\n\\n安装成功后，查看版本信息。\\n\\n```\\ndeveco --version\\n```\\n\\n![](assets/image-20260709112622225.png)\\n\\n## DevEcoCode 启动\\n\\n启动命令如下\\n\\n```\\ndeveco\\n```\\n\\n需要注意的是，首次使用需要登录你的华为开发者账号。\\n\\n![](assets/image-20260709113513130.png)\\n\\n登录之后，可以使用 DevEcoCode 提供的免费 GLM 5.1 模型，输入 `/model` 进行选择，另外免费模型在高峰期可能会出现排队的情况。\\n\\n![image-20260709114201159](assets/image-20260709114201159.png)\\n\\n## DevEcoCode 接入自己的模型\\n\\n当然，DevEcoCode 也支持接入自己的大模型，进入 `/model` 后，按下 `Ctrl + A` 即可。\\n\\n![](assets/image-20260709114810159.png)\\n\\n当前DevEcoCode 支持接入市场上大部分的大模型，列表如下。\\n\\n> DevEcoCode是基于opencode，支持的模型也是来自于opencode中定义的 https://models.dev/api.json\\n>\\n> 目前收录了 122 个 Provider。\\n\\n![](assets/image-20260709130954284.png)\\n\\n\\n\\n\\n\\n大家可以根据自己已有的来选择接入，万少这里接入了智谱和 DeepSeek 的套餐，这里拿 DeepSeek 为例。\\n\\n选择 DeepSeek。\\n\\n![](assets/image-20260709115138993.png)\\n\\n---\\n\\n然后会提醒你输入DeepSeek的API key\\n\\n![](assets/image-20260709115508859.png)\\n\\n登录你的DeepSeek的API开发平台\\n\\n> https://platform.deepseek.com/api_keys\\n\\n复制或者新建一个API Key\\n\\n![](assets/image-20260709115450561.png)\\n\\n---\\n\\n把Api key 填写进去即可，按下**Enter**进行确认。\\n\\n![](assets/image-20260709115625515.png)\\n\\n因为目前 DeepSeek 提供了 flash 和 pro 两个版本，开发者可以再次输入 `/model` 来选择和切换。\\n\\n![](assets/image-20260709115804390.png)\\n\\n---\\n\\n### 手动编辑配置文件接入模型\\n\\n开发者也可以手动编辑配置文件来接入大模型\\n\\n## DevEcoCode 开发应用流程\\n\\n因为DevEcoCode是基于开源的OpenCode二次封装的，所以OpenCode的大部分已有的功能DevEcoCode也支持。\\n\\n这里以一个开发新的HarmonyOS为例。\\n\\n整个开发流程可以用下图概括：\\n\\n![DevEcoCode 开发应用流程](assets/dev-workflow.png)\\n\\n\\n\\n### 新建一个鸿蒙工程\\n\\n使用DevEcoCode不像之前的DevEcoCli需要记住命令，这里开发者直接使用自然语言即可。\\n\\n```\\n在当前目录下帮我创建一个API版本为21的HarmonyOS应用的工程\\n```\\n\\n![](assets/image-20260709123537975.png)\\n\\n---\\n\\n然后根据提示完成其他流程操作即可。\\n\\n![](assets/image-20260709123823615.png)\\n\\n---\\n\\n![](assets/image-20260709124042817.png)\\n\\n### 启动工程和预览\\n\\n![](assets/image-20260709124451750.png)\\n\\n![](assets/image-20260709125229725.png)\\n\\n### 自然语言实现功能\\n\\n然后你可以使用自然语言去实现你的功能，当DevEcoCode碰到自己不是很了解的知识时，它自己会调用DevEcoCli搜索文档的能力在本地的SDK库中去寻找资料，所以很快也很准确可以获取到技术，这个如果是用其他的AI agent可能默认会调用内置的Fetch工具在互联网上搜索资料，这样就太慢和笼统了，很容易失败！\\n\\n```\\n帮我使用系统组件 沉浸式光感的tab实现  首页、分类、我的 ，其中的tab的图标帮我优先使用内置的图标，如果没有，帮我创建svg，不要使用emoji图标\\n```\\n\\n![](assets/image-20260709125454619.png)\\n\\n---\\n\\n需要注意的是，因为沉浸式光感是API23才有的，API21的工程不支持，这一点，DevEcoCode也识别出来了。\\n\\n![](assets/image-20260709125700685.png)\\n\\n实际开发中，你可以直接中断对话，然后补上你的要求，及时调整方向。\\n\\n当devecocode明确方案后，便会开始执行任务。\\n\\n![](assets/image-20260709130341246.png)\\n\\n得到效果。\\n\\n![](assets/PixPin_2026-07-09_13-10-32.gif)\\n\\n### 执行构建\\n\\n需要注意的是，刚刚创建的工程使用的是自动签名。如果想要运行到真机，或者进行构建打包等操作，最后都先配置成手动签名，然后继续在已有的工程内开发。\\n\\n想要执行构建，也是直接用自然语言对话即可。\\n\\n```\\n帮我构建生产环境下的 APP 包 xxxxx\\n```\\n\\n### 多模态\\n\\nDevEcoCode 登录华为账号时，默认使用内置的 Qwen3-VL 多模态模型进行 UI 检查，该模型只能用于 UI 检查（非主动调用）。如果开发者想要在自然语言对话中使用多模态能力，目前只支持接入 Qwen 系列的多模态模型。\\n\\n\\n\\n## DevEcoCode 开发方式\\n\\nDevEcoCode 支持 3 种开发方式，默认是 Build（按 Tab 进行切换）。\\n\\n- `Build`：默认模式，适合工程生成、代码生成、配置修正、测试执行、推包运行和发布执行。\\n- `Plan`：适合需求拆解、技术方案、发布规划、测试规划和文档生成。\\n  - 不会改动文件，只做计划和方案。\\n- `Goal`：适合 SDD 五阶段从需求到实现与构建验证的端到端特性交付。\\n  - 适合复杂任务。\\n\\n按照任务的复杂度来使用：\\n\\n1. 简单的直接使用Build模式。\\n2. 稍微复杂的，先 Plan 做好计划，再切换到 Build 模式。\\n3. 最复杂的任务使用Goal模式。\\n\\n三种开发方式的对比如下图所示：\\n\\n![DevEcoCode 三种开发方式](assets/dev-modes.png)\\n\\n## DevEcoCode 常见能力\\n\\nDevEcoCode是基于OpenCode，因此常见的一些能力，如agent、skill、mcp等也都支持和通用。\\n\\n-  `/init` — [OpenCode 文档](https://opencode.ai/docs/tui#init) 中提供的引导式工程初始化命令，让 AI 自动扫描仓库并生成 AGENTS.md\\n-   `AGENTS.md` — [OpenCode 官方约定](https://opencode.ai/docs/zh-cn/rules/) 中定义的 AI 工程说明书，向 AI 描述仓库的代码风格、构建方式和开发约定\\n-   **agent（代理**） — [OpenCode Agent 系统](https://opencode.ai/docs/zh-cn/agents/#%E9%85%8D%E7%BD%AE) 中的专职子代理机制，主 Agent 可将特定任务（调试、编码、验证）委托给它独立完成\\n-   **Skill（技能**） — [OpenCode Skill 机制](https://opencode.ai/docs/skills) 中用 Markdown 编写的专业知识包，AI 在需要时按名称加载使用\\n-   **MCP** — [Model Context Protocol](https://opencode.ai/docs/zh-cn/mcp-servers/) 开放标准，让 AI 通过统一协议接入外部工具服务器\\n-  **plugins** — [编写自己的插件来扩展 DevEcoCode](https://opencode.ai/docs/zh-cn/plugins/)。\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n## DevEcoCode 常见命令一览\\n\\n\\n### DevEcoCode 斜杠命令 \\n\\n| 命令 | 别名 | 分类 | 描述 | 来源 |\\n|------|------|------|------|------|\\n| `/init` | — | 工程 | 引导式 AGENTS.md 生成，让 AI 自动分析工程并输出工程规范文件 | 内置 `command` |\\n| `/debug` | — | 调试 | 以运行时证据驱动 ArkTS 问题调试 | 内置 `command` |\\n| `/review` | — | 审查 | 审查代码变更（支持 commit / branch / PR，默认未提交变更） | 内置 `command` |\\n| `/editor` | — | 会话 | 在外部编辑器中编写提示内容 | 内置 `tui` |\\n| `/new` | `/clear` | 会话 | 启动一个新的会话 | 内置 `tui` |\\n| `/exit` | — | 会话 | 关闭 DevEcoCode | 内置 `tui` |\\n| `/skills` | — | 提示 | 列出所有可用的 Skill 并按需加载 | 内置 `command` |\\n| `/status` | — | 系统 | 查看当前系统状态（MCP 连接、Workspace 等） | 内置 `tui` |\\n| `/models` | `/mo` | Agent | 切换当前使用的模型和 Provider | 内置 `tui` |\\n| `/agents` | — | Agent | 切换 Agent（build / goal 等） | 内置 `tui` |\\n| `/mcps` | — | Agent | 管理 MCP 服务器启用/禁用 | 内置 `tui` |\\n| `/variants` | — | Agent | 切换当前模型的变体（如 effort 级别） | 内置 `tui` |\\n| `/connect` | — | Provider | 连接 AI Provider（登录/添加 API Key） | 内置 `tui` |\\n| `/sessions` | `/resume`, `/continue` | 会话 | 切换/恢复历史会话 | 内置 `tui` |\\n| `/org` | `/orgs`, `/switch-org` | 账号 | 切换组织（仅登录后可见） | 内置 `tui` |\\n| `/workspaces` | — | 工作区 | 管理工作区（实验性功能） | 内置 `tui` |\\n| 用户自定义命令 | — | 工程 | 在 `deveco.jsonc` 的 `command` 段中配置的自定义命令，可绑定 Agent、模型 | 配置 |\\n| MCP 注册命令 | `/:name:mcp` | 扩展 | 已连接的 MCP Server 通过 Prompt 能力注册为斜杠命令 | MCP |\\n| Skill 注册命令 | — | 技能 | 工程内 `SKILL.md` 自动注册为可调用的斜杠命令（不与其他命令重名时） | Skill |\\n\\n\\n\\n### DevEcoCode CLI 终端命令 \\n\\n| 命令 | 描述 |\\n|------|------|\\n| `deveco` | 不带参数时启动 TUI 交互界面（默认入口） |\\n| `deveco run [message..]` | 直接以指定消息运行 DevEcoCode（非交互模式） |\\n| `deveco serve` | 启动无头（headless）DevEco 服务器 |\\n| `deveco web` | 启动服务器并在浏览器中打开 Web 界面 |\\n| `deveco attach <url>` | 连接到正在运行的 DevEco 服务器 |\\n| `deveco acp` | 启动 ACP（Agent Client Protocol）服务器 |\\n| `deveco models [provider]` | 列出所有可用模型，可按 Provider 过滤 |\\n| `deveco providers` | 管理 AI Provider 和认证凭据 |\\n| `deveco login [url]` | 登录 DevEcoCode / OpenCode 账号 |\\n| `deveco mcp` | 管理 MCP（Model Context Protocol）服务器 |\\n| `deveco session` | 管理会话（列表、查看、删除等） |\\n| `deveco agent create` | 创建新的 Agent |\\n| `deveco export [sessionID]` | 将会话数据导出为 JSON |\\n| `deveco import <file>` | 从 JSON 文件或 URL 导入会话数据 |\\n| `deveco plugin <module>` | 安装插件并更新配置 |\\n| `deveco pr <number>` | 拉取并切换到 GitHub PR 分支，然后启动 deveco |\\n| `deveco stats` | 查看 Token 用量和费用统计 |\\n| `deveco db [query]` | 打开交互式 SQLite shell 或执行查询 |\\n| `deveco generate` | 生成代码/配置（内置脚手架） |\\n| `deveco upgrade [target]` | 升级 DevEcoCode 到最新或指定版本 |\\n| `deveco uninstall` | 卸载 DevEcoCode 并清除所有相关文件 |\\n\\n## DevEcoCode 配置文件\\n\\nDevEcoCode支持3种配置文件，优先级如下：\\n\\n1. 项目目录下 `.deveco/deveco.jsonc`\\n2. 项目目录下 `deveco.jsonc`\\n3. 用户目录下 `.config/deveco/deveco.jsonc`\\n\\n完整配置一览：\\n\\n```json\\n{\\n  // 推荐始终声明，编辑器会据此做实时校验\\n  \\"$schema\\": \\"https://opencode.ai/config.json\\",\\n\\n  // ── 基础 ──────────────────────────────────────────\\n  \\"username\\": \\"alice\\",\\n  \\"shell\\": \\"/bin/zsh\\",                       // 终端和 bash 工具用的默认 shell\\n  \\"logLevel\\": \\"INFO\\",                        // DEBUG | INFO | WARN | ERROR\\n  \\"model\\": \\"anthropic/claude-sonnet-4-6\\",    // 始终带 provider 前缀\\n  \\"small_model\\": \\"anthropic/claude-haiku-4-5\\",\\n  \\"default_agent\\": \\"build\\",                  // 必须指向一个非隐藏的 primary agent\\n  \\"autoupdate\\": \\"notify\\",                    // true | false | \\"notify\\"\\n  \\"share\\": \\"manual\\",                         // \\"manual\\" | \\"auto\\" | \\"disabled\\"\\n  \\"snapshot\\": true,                          // 文件快照（undo/revert），默认 true\\n\\n  // ── 指令 / 技能 / 引用 ───────────────────────────\\n  \\"instructions\\": [\\"AGENTS.md\\", \\"docs/style.md\\"],\\n  \\"skills\\": {                                // 注意是对象，不是数组\\n    \\"paths\\": [\\".deveco/skills\\", \\"/abs/path\\"],\\n    \\"urls\\": [\\"https://example.com/.well-known/skills/\\"]\\n  },\\n  \\"references\\": {                            // 以别名建立 @ 自动补全的上下文\\n    \\"docs\\": { \\"path\\": \\"../docs\\", \\"description\\": \\"产品文档\\" },\\n    \\"sdk\\": { \\"repository\\": \\"Effect-TS/effect\\", \\"branch\\": \\"main\\", \\"hidden\\": true }\\n  },\\n  \\"watcher\\": { \\"ignore\\": [\\"**/dist/**\\"] },\\n\\n  // ── Agent（单数，对象）────────────────────────────\\n  // 键名可以是内置：plan/build/general/explore/title/summary/compaction\\n  // 也可以是自定义 agent 名\\n  \\"agent\\": {\\n    \\"build\\": { \\"model\\": \\"anthropic/claude-sonnet-4-6\\" },\\n    \\"my-reviewer\\": {\\n      \\"description\\": \\"审查 PR 风格问题\\",\\n      \\"mode\\": \\"subagent\\",                    // \\"primary\\" | \\"subagent\\" | \\"all\\"\\n      \\"model\\": \\"anthropic/claude-sonnet-4-6\\",\\n      \\"variant\\": \\"default\\",\\n      \\"temperature\\": 0.2,\\n      \\"top_p\\": 1.0,\\n      \\"steps\\": 50,                           // 最大迭代轮数\\n      \\"color\\": \\"#FF5733\\",                    // 或 primary/secondary/...\\n      \\"hidden\\": false,\\n      \\"disable\\": false,\\n      \\"permission\\": { \\"edit\\": \\"deny\\", \\"bash\\": \\"ask\\" }\\n      // prompt 建议写在 .deveco/agent/<name>.md 文件里，而非内联\\n    }\\n  },\\n\\n  // ── Command（单数，对象）──────────────────────────\\n  \\"command\\": {\\n    \\"deploy\\": {\\n      \\"template\\": \\"执行部署：$ARGUMENTS\\",     // 必填，命令正文；$ARGUMENTS/$1/$2...\\n      \\"description\\": \\"部署当前工程\\",\\n      \\"agent\\": \\"build\\",\\n      \\"model\\": \\"anthropic/claude-sonnet-4-6\\",\\n      \\"variant\\": \\"default\\",\\n      \\"subtask\\": false\\n    }\\n  },\\n\\n  // ── Provider（单数）──────────────────────────────\\n  \\"enabled_providers\\": [\\"anthropic\\"],        // 设置后，仅这些 provider 生效\\n  \\"disabled_providers\\": [\\"openai\\"],\\n  \\"provider\\": {\\n    \\"anthropic\\": {\\n      \\"name\\": \\"Anthropic\\",\\n      \\"api\\": \\"https://api.anthropic.com/v1\\",\\n      \\"env\\": [\\"ANTHROPIC_API_KEY\\"],\\n      \\"npm\\": \\"@ai-sdk/anthropic\\",\\n      \\"options\\": {\\n        \\"apiKey\\": \\"sk-...\\",\\n        \\"baseURL\\": \\"https://api.anthropic.com/v1\\",\\n        \\"timeout\\": 60000,                   // ms；设 false 关闭超时\\n        \\"headerTimeout\\": 10000,\\n        \\"chunkTimeout\\": 5000\\n      },\\n      \\"models\\": {                           // 模型覆盖/自定义\\n        \\"claude-sonnet-4-6\\": {\\n          \\"name\\": \\"Claude Sonnet 4.6\\",\\n          \\"attachment\\": true,\\n          \\"reasoning\\": true,\\n          \\"tool_call\\": true,\\n          \\"limit\\": { \\"context\\": 200000, \\"input\\": 190000, \\"output\\": 8000 },\\n          \\"cost\\": { \\"input\\": 3.0, \\"output\\": 15.0 }\\n        }\\n      }\\n    }\\n  },\\n\\n  // ── MCP（单数，对象）──────────────────────────────\\n  \\"mcp\\": {\\n    \\"playwright\\": {                          // 本地进程型\\n      \\"type\\": \\"local\\",                       // 必填\\n      \\"command\\": [\\"npx\\", \\"-y\\", \\"@playwright/mcp\\"],  // 数组，不是字符串\\n      \\"cwd\\": \\".\\",\\n      \\"environment\\": { \\"BROWSER\\": \\"chromium\\" },\\n      \\"enabled\\": true,\\n      \\"timeout\\": 5000\\n    },\\n    \\"remote-thing\\": {                        // 远程型\\n      \\"type\\": \\"remote\\",\\n      \\"url\\": \\"https://mcp.example.com/sse\\",\\n      \\"headers\\": { \\"Authorization\\": \\"Bearer {env:TOKEN}\\" }, // {env:VAR} / {file:path} 插值\\n      \\"oauth\\": { \\"clientId\\": \\"...\\", \\"scope\\": \\"...\\" },       // 或 false 关闭自动探测\\n      \\"enabled\\": true\\n    },\\n    \\"old\\": { \\"enabled\\": false }              // 关闭继承自父配置的服务器\\n  },\\n\\n  // ── Plugin（数组！）──────────────────────────────\\n  \\"plugin\\": [                                // 数组，不是对象\\n    \\"opencode-gemini-auth\\",                  // npm 包名\\n    \\"opencode-foo@1.2.3\\",                    // 锁定版本\\n    \\"./local-plugin.ts\\",                     // 相对路径\\n    [\\"opencode-bar\\", { \\"key\\": \\"val\\" }]       // [name, options] 元组\\n  ],\\n\\n  // ── Permission ───────────────────────────────────\\n  \\"permission\\": {                            // 或顶层字符串 \\"allow\\"（很少用）\\n    \\"edit\\": \\"deny\\",\\n    \\"bash\\": { \\"git *\\": \\"allow\\", \\"rm *\\": \\"deny\\", \\"*\\": \\"ask\\" }, // 对象内插入顺序重要，取最后匹配\\n    \\"external_directory\\": { \\"~/secrets/**\\": \\"deny\\", \\"*\\": \\"allow\\" },\\n    \\"todowrite\\": \\"allow\\",                    // 这些只接受扁平 action：todowrite/question/webfetch/websearch/doom_loop\\n    \\"read\\": \\"allow\\"\\n  },\\n\\n  // ── 输出 / 压缩 / 附件 / 服务 ────────────────────\\n  \\"tool_output\\": { \\"max_lines\\": 2000, \\"max_bytes\\": 51200 },\\n  \\"compaction\\": { \\"auto\\": true, \\"prune\\": false, \\"tail_turns\\": 2, \\"reserved\\": 1000 },\\n  \\"attachment\\": { /* 图片大小限制、缩放行为 */ },\\n  \\"formatter\\": true,                         // false | true | { 覆盖项 }\\n  \\"lsp\\": true,\\n  \\"server\\": {                                // opencode serve / web\\n    \\"port\\": 4096,\\n    \\"hostname\\": \\"0.0.0.0\\",\\n    \\"mdns\\": true,\\n    \\"mdnsDomain\\": \\"deveco.local\\",\\n    \\"cors\\": [\\"https://app.example.com\\"]\\n  },\\n\\n  // ── 实验性 ───────────────────────────────────────\\n  \\"experimental\\": {\\n    \\"batch_tool\\": true,\\n    \\"openTelemetry\\": false,\\n    \\"primary_tools\\": [\\"edit\\"],\\n    \\"continue_loop_on_deny\\": false,\\n    \\"mcp_timeout\\": 30000,\\n    \\"disable_paste_summary\\": false,\\n    \\"policies\\": []\\n  },\\n\\n  // ── DevEcoCode 特有：合规/法律（可选，全部回退到内置默认值）──\\n  \\"agreement\\": {\\n    \\"tms_url\\": \\"\\",\\n    \\"privacy_url\\": \\"\\",\\n    \\"terms_url\\": \\"\\",\\n    \\"privacy_id\\": \\"\\",\\n    \\"terms_id\\": \\"\\"\\n  }\\n\\n  // ── 已废弃字段（能用但建议迁移）─────────────────\\n  // \\"mode\\": { ... }            → 用 \\"agent\\"\\n  // \\"reference\\": { ... }       → 用 \\"references\\"\\n  // \\"autoshare\\": true          → 用 \\"share\\": \\"auto\\"\\n  // \\"tools\\": { \\"edit\\": true }  → 用 \\"permission\\"\\n  // \\"layout\\": \\"stretch\\"        → 已固定为 stretch\\n  // \\"maxSteps\\"                 → 用 \\"steps\\"\\n}\\n```\\n\\n\\n\\n\\n\\n## 总结\\n\\n本文从 DevEcoCli 的使用痛点出发，介绍了鸿蒙官方推出的 AI Agent 工具 DevEcoCode，要点回顾如下：\\n\\n- **产品定位**：DevEcoCode 基于开源 OpenCode 扩展，专为 HarmonyOS 开发而生，底层通过 MCP 调用 DevEcoCli，复用 DevEco Studio 全套工具链（ohpm、hvigor、hdc、emulator、hilog）。\\n- **核心优势**：相比直接使用 DevEcoCli 死记命令，DevEcoCode 用**自然语言对话**即可完成新建工程、编码、构建、运行和调试，门槛更低、效率更高，也更能释放工具链的全部能力。\\n- **上手路径**：备齐前置环境（Node.js 22+、DevEco Studio 6.1+、`DEVECO_HOME` 环境变量）与 DevEcoCli → 执行 `npm install -g @deveco/deveco-code` 安装 → 输入 `deveco` 启动并登录华为账号 → 按需选择自带免费模型或接入自己的大模型。\\n- **开发方式**：根据任务复杂度，在 **Build（默认，直接执行）/ Plan（只规划不改文件）/ Goal（端到端 SDD 五阶段）** 三种模式间选择，用 Tab 切换。\\n- **生态能力**：天然继承 OpenCode 的 agent、skill、mcp、plugin 等机制，并可通过 `deveco.jsonc` 灵活配置 Provider、Agent、Command、权限等。\\n\\n一句话概括：**DevEcoCode = DevEcoCli 的工具能力 + OpenCode 的 AI 交互体验**，让鸿蒙开发真正进入\\"动嘴就能开发\\"的阶段。如果你已经在用 DevEcoCli，强烈建议搭配 DevEcoCode，把精力从记命令转移到业务本身。\\n\\n## 参考文献\\n\\n1. DevEco Studio 工具概览：https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/ide-tools-overview\\n2. DevEcoCode：鸿蒙专属AI智能体：https://atomgit.com/openharmony-sig/deveco-code\\n3. @deveco/deveco-cli · npm：https://www.npmjs.com/package/@deveco/deveco-cli\\n4. HarmonyOS 7新特性：https://developer.huawei.com/consumer/cn/features/?ha_source=51cto&ha_sourceId=70000008\\n5. HarmonyOS AI开发提效工具：DevEco Code & DevEco CLI：https://developer.huawei.com/consumer/cn/forum/topic/0202216647056043902?ha_source=51cto&ha_sourceId=70000008\\n6. 社区干货合集：一帖看全，高效查阅 https://developer.huawei.com/consumer/cn/forum/topic/0201215860119833282?ha_source=51cto&ha_sourceId=70000008\\n7. opencode：[OpenCode](https://opencode.ai/docs/zh-cn) 是一个开源的 AI 编码代理。它提供终端界面、桌面应用和 IDE 扩展等多种使用方式。\\n\\n"}'),P={name:"鸿蒙开发技巧/手把手带你上手鸿蒙应用开发利器 DevEcoCli和DevEcoCode/02-手把手带你上手鸿蒙应用开发利器 DevEcoCode/手把手带你上手鸿蒙应用开发利器 DevEcoCode.md"};function S(w,s,I,O,x,T){return n(),a("div",null,[...s[0]||(s[0]=[e("",116)])])}const N=i(P,[["render",S]]);export{M as __pageData,N as default};
